beforeSaveCustomScript:
if (name == null || name == '') {
    $categoryLabel = language\translateOption(category, 'category', 'ActivityOfferSlot');
    $datePart = datetime\format(dateStart, 'DD.MM.YYYY');
    $placePart = '';
    if (placeStreet != null && placeStreet != '') {
        $placePart = placeStreet;
    } else if (placeCity != null && placeCity != '') {
        $placePart = placeCity;
    }
    if ($placePart != '') {
        name = string\concatenate($categoryLabel, ' | ', $datePart, ' | ', $placePart);
    } else {
        name = string\concatenate($categoryLabel, ' | ', $datePart);
    }
}
